import numpy as np, mujoco, rcb_dtb
from scipy.spatial.transform import Rotation as Rot
import imageio.v2 as im

class Control:
 def __init__(self,s):
  self.s=s;self.m=s.model;self.d=s.data;self.k=mujoco.MjData(self.m);self.bid=self.m.body('palmleft_hand_C_MC').id
  self.q=s.state()['q'].copy(); self.jp=np.zeros((3,self.m.nv));self.jr=self.jp.copy()
 def pose(self):return self.d.xpos[self.bid].copy(),self.d.xmat[self.bid].reshape(3,3).copy()
 def ik(self,p,R,q=None,iters=80):
  q=self.q.copy() if q is None else q.copy(); self.k.qpos[:]=self.d.qpos
  for it in range(iters):
   self.k.qpos[self.s._jq]=q;mujoco.mj_forward(self.m,self.k)
   ep=p-self.k.xpos[self.bid];er=Rot.from_matrix(R@self.k.xmat[self.bid].reshape(3,3).T).as_rotvec()
   e=np.r_[ep,er*.3]
   if np.linalg.norm(e)<1e-5:break
   mujoco.mj_jacBody(self.m,self.k,self.jp,self.jr,self.bid)
   J=np.r_[self.jp[:,:7],self.jr[:,:7]*.3];dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*1e-5,e)
   dq=np.clip(dq,-.12,.12);q[:7]=np.clip(q[:7]+dq,self.s.lower[:7]+.001,self.s.upper[:7]-.001)
  return q
 def step(self,q):self.q=q.copy();return self.s.step(q)
 def hold(self,n):
  for i in range(n):self.step(self.q)
 def move(self,p,R,n=120,hand=None):
  p0,R0=self.pose(); rv=Rot.from_matrix(R@R0.T).as_rotvec();h0=self.q[7:].copy()
  for i in range(n):
   a=(i+1)/n;a=a*a*(3-2*a)
   q=self.ik(p0*(1-a)+p*a,Rot.from_rotvec(rv*a).as_matrix()@R0,iters=8)
   if hand is not None:q[7:]=h0*(1-a)+np.array(hand)*a
   self.step(q)
 def fingers(self,h,n=120):
  q0=self.q.copy()
  for i in range(n):
   a=(i+1)/n;q=q0.copy();q[7:]=q0[7:]*(1-a)+np.array(h)*a;self.step(q)
 def snapshot(self,name):im.imwrite('/app/output/'+name+'.png',self.s.render_grid(size=(640,480)))
 def contacts(self):
  for con in self.d.contact:
   if self.s._obj in self.m.geom_bodyid[[con.geom1,con.geom2]]:
    print(self.m.geom(con.geom1).name,self.m.geom(con.geom2).name,round(con.dist,5))

def hand(cmc=1.2,mcp=.5,pip=1.5,dip=1.2,thumb=[1.2,0,.5,0,.5]):
 h=np.zeros(22);h[:5]=thumb
 for ids in [[5,7,8],[9,11,12],[13,15,16],[18,20,21]]:h[ids]=[mcp,pip,dip]
 return h

if __name__=='__main__':
 s=rcb_dtb.Session();c=Control(s);s.record_start()
 R=np.array([[0,1,0],[0,0,-1],[-1,0,0.]])
 c.hold(30);obj=s.state()['object_pos'];print('settled',s.state())
 p=obj-R@np.array([.04,0,.12]);c.move(p+[0,0,.10],R,150);c.snapshot('above')
 c.move(p,R,120);c.snapshot('down');print('down',s.state());c.contacts()
 c.fingers(hand(),120);c.snapshot('closed');print('closed',s.state());c.contacts()
 c.move(p+[0,0,.15],R,180);c.hold(60);c.snapshot('lift');print('lift',s.state());c.contacts()
 A=s.record_stop();s.save_trajectory(A,'/app/output/test.npz')
PY
